def select(models, y):
    rmse = scores(models, y, CAL)  # CAL = readings from 0-8 h
    return min(rmse, key=rmse.get)

def screen(rows, k=2):
    keep = sorted(rows, key=lambda r: -r['oat_swing'])[:k]
    return [r['input'] for r in keep]

def run(order):
    T, u = 15.0, 0.0
    for _ in range(2):
        T_old = T
        T = T + 2.0 * u
        seen = T_old if order == 'jacobi' else T
        u = 0.5 * (21.0 - seen)
    return round(T, 2), round(u, 2)

print(run('jacobi'), run('gauss-seidel'))

